/** 🧮️ Attributes the generated bytes of each script chunk of a source-mapped site build to its sources (raw minified
 * bytes, grouped by a directory prefix), so the entry's growth can be traced to modules.
 * Usage: `bun attribute_site_chunks.ts <dist> [depth]` */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { SourceMapConsumer } from "source-map-js";

const dist = process.argv[2]!;
const depth = Number(process.argv[3] ?? 6);
const group = (source: string): string => {
  const clean = source.replace(/\\/gu, "/").replace(/^(\.\.\/)+/u, "").replace(/^.*node_modules\//u, "node_modules/");
  const parts = clean.split("/");
  return clean.startsWith("node_modules/") ? parts.slice(0, parts[1]!.startsWith("@") ? 3 : 2).join("/") : parts.slice(0, depth).join("/");
};
for (const name of readdirSync(join(dist, "assets")).filter((file) => file.endsWith(".js"))) {
  const code = readFileSync(join(dist, "assets", name), "utf8");
  const consumer = new SourceMapConsumer(JSON.parse(readFileSync(join(dist, "assets", `${name}.map`), "utf8")));
  const lines = code.split("\n");
  const bytes = new Map<string, number>();
  const marks: { line: number; column: number; source: string }[] = [];
  consumer.eachMapping((mapping) => marks.push({ line: mapping.generatedLine, column: mapping.generatedColumn, source: mapping.source ? group(mapping.source) : "(unmapped)" }));
  marks.sort((a, b) => a.line - b.line || a.column - b.column);
  marks.forEach((mark, index) => {
    const next = marks[index + 1];
    const end = next && next.line === mark.line ? next.column : lines[mark.line - 1]!.length;
    bytes.set(mark.source, (bytes.get(mark.source) ?? 0) + Math.max(0, end - mark.column));
  });
  const total = code.length;
  console.log(`\n== ${name} ${total} chars`);
  for (const [source, size] of [...bytes].sort((a, b) => b[1] - a[1]).slice(0, 60)) console.log(`${String(size).padStart(9)} ${(100 * size / total).toFixed(1).padStart(5)}%  ${source}`);
}
